CREATE TABLE owner_account (id integer PRIMARY KEY CHECK(id=1), username text NOT NULL UNIQUE, password_hash text NOT NULL, totp_secret text NOT NULL, last_totp_step bigint NOT NULL DEFAULT -1, session_version bigint NOT NULL DEFAULT 0);
CREATE TABLE app_settings(scope text PRIMARY KEY, version bigint NOT NULL DEFAULT 0, body jsonb NOT NULL DEFAULT '{}');
INSERT INTO app_settings(scope,body) VALUES ('global','{"enabled":false,"name":"","biography":"","tone":"Тепло, живо, коротко, без канцелярита","examples":[],"avoidExamples":[],"emoji":["🙂","😄"],"slang":"умеренно","profanity":false,"maxReplyChars":800,"quietSeconds":8,"maxBurstSeconds":30,"delayMinSeconds":2,"delayMaxSeconds":6,"historyDays":30,"historyLimit":1000,"messageRetentionDays":180,"fileRetentionDays":30,"monthlyBudgetUsd":30,"replyModel":"gpt-5.4","memoryModel":"gpt-5.4-mini","transcriptionModel":"gpt-4o-mini-transcribe","timezone":"Europe/Kyiv","quietHoursStart":"","quietHoursEnd":"","identityReaction":"Отвечай в голосе профиля, спокойно при серьёзном раздражении","commitments":{"meetings":{"mode":"DRAFT","rule":""},"promises":{"mode":"DRAFT","rule":""},"money":{"mode":"DRAFT","rule":""},"personal":{"mode":"DRAFT","rule":""}}}');
CREATE TABLE credential(name text PRIMARY KEY, encrypted_value text NOT NULL);
CREATE TABLE connection(id uuid PRIMARY KEY, name text NOT NULL, adapter text NOT NULL CHECK(adapter IN ('telegram','fake')), status text NOT NULL DEFAULT 'DISCONNECTED', auth_state jsonb NOT NULL DEFAULT '{}', self_id text, created_at timestamptz NOT NULL DEFAULT now(), enabled boolean NOT NULL DEFAULT false);
CREATE TABLE conversation(id uuid PRIMARY KEY, connection_id uuid NOT NULL REFERENCES connection(id) ON DELETE CASCADE, external_id text NOT NULL, title text NOT NULL, selected boolean NOT NULL DEFAULT false, mode text NOT NULL DEFAULT 'PAUSED', status text NOT NULL DEFAULT 'PAUSED', version bigint NOT NULL DEFAULT 0, imported boolean NOT NULL DEFAULT false, import_cancelled boolean NOT NULL DEFAULT false, import_count integer NOT NULL DEFAULT 0, summary text NOT NULL DEFAULT '', summary_version bigint NOT NULL DEFAULT 0, needs_attention text, last_activity timestamptz NOT NULL DEFAULT now(), UNIQUE(connection_id,external_id));
CREATE TABLE message(id uuid PRIMARY KEY, conversation_id uuid NOT NULL REFERENCES conversation(id) ON DELETE CASCADE, external_id text NOT NULL, direction text NOT NULL, source text NOT NULL, kind text NOT NULL DEFAULT 'TEXT', body text NOT NULL DEFAULT '', sent_at timestamptz NOT NULL, historical boolean NOT NULL DEFAULT false, handled boolean NOT NULL DEFAULT false, deleted boolean NOT NULL DEFAULT false, ephemeral boolean NOT NULL DEFAULT false, reply_to text, revision bigint NOT NULL DEFAULT 0, delivery_status text NOT NULL DEFAULT 'RECEIVED', UNIQUE(conversation_id,external_id));
CREATE INDEX message_history ON message(conversation_id,sent_at DESC,id DESC);
CREATE INDEX message_search ON message USING gin(to_tsvector('simple',body));
CREATE TABLE attachment(id uuid PRIMARY KEY, message_id uuid NOT NULL REFERENCES message(id) ON DELETE CASCADE, external_file_id text NOT NULL, kind text NOT NULL, mime_type text NOT NULL, size_bytes bigint NOT NULL DEFAULT 0, duration_seconds integer NOT NULL DEFAULT 0, local_name text, status text NOT NULL DEFAULT 'PENDING', transcript text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE automation_job(conversation_id uuid PRIMARY KEY REFERENCES conversation(id) ON DELETE CASCADE, context_version bigint NOT NULL, first_at timestamptz NOT NULL, due_at timestamptz NOT NULL, state text NOT NULL DEFAULT 'WAITING', lease_token uuid, lease_until timestamptz, attempts integer NOT NULL DEFAULT 0);
CREATE INDEX job_due ON automation_job(due_at) WHERE state='WAITING';
CREATE TABLE outbound(id uuid PRIMARY KEY, conversation_id uuid NOT NULL REFERENCES conversation(id) ON DELETE CASCADE, request_key text NOT NULL UNIQUE, context_version bigint NOT NULL, body text NOT NULL, source text NOT NULL, status text NOT NULL, due_at timestamptz NOT NULL, temporary_id text, external_id text, sending_id integer, reason text, attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbound_due ON outbound(due_at) WHERE status='READY';
CREATE TABLE memory_fact(id uuid PRIMARY KEY, conversation_id uuid NOT NULL REFERENCES conversation(id) ON DELETE CASCADE, subject text NOT NULL, fact_key text NOT NULL, content text NOT NULL, pinned boolean NOT NULL DEFAULT false, conflict text, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(conversation_id,subject,fact_key));
CREATE TABLE fact_source(fact_id uuid NOT NULL REFERENCES memory_fact(id) ON DELETE CASCADE, message_id uuid NOT NULL REFERENCES message(id) ON DELETE CASCADE, PRIMARY KEY(fact_id,message_id));
CREATE TABLE memory_tombstone(conversation_id uuid NOT NULL REFERENCES conversation(id) ON DELETE CASCADE, fact_key text NOT NULL, source_id uuid NOT NULL, PRIMARY KEY(conversation_id,fact_key,source_id));
CREATE TABLE usage_entry(id uuid PRIMARY KEY, conversation_id uuid REFERENCES conversation(id) ON DELETE SET NULL, kind text NOT NULL, model text NOT NULL, prompt_version text NOT NULL, state text NOT NULL, reserved_usd numeric(14,6) NOT NULL CHECK(reserved_usd>=0), actual_usd numeric(14,6), input_tokens bigint, output_tokens bigint, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE INDEX usage_month ON usage_entry(created_at);
CREATE TABLE audit_event(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, category text NOT NULL, entity_id text, created_at timestamptz NOT NULL DEFAULT now());
